# Server-side validation for the deployment-gated ValidatingAdmissionPolicies.
#
# The CEL expressions in validatingadmissionpolicy.yaml cannot be compiled
# offline; this script validates them against a live API server, then probes
# enforcement. It must be run by an operator with kubectl access to the target
# ACK cluster, from anywhere:
#
#   QR_APPLY_TEST_CANARY=1 .github/runner-scale-sets/query-regression/ack/apply-test.sh
#
# Offline modes (no kubectl, no cluster):
#
#   1. Prove that every negative Job mutation reads the manifest JSON from
#      stdin, emits valid JSON, and changes the expected field, then exit:
#
#        QR_APPLY_TEST_SELF=1 .github/runner-scale-sets/query-regression/ack/apply-test.sh
#
#   2. Prove the fail-closed Job lookup and the canary cleanup confirmation
#      state machine behaviorally with temporary PATH stubs (stub kubectl and
#      stub timeout executables; no real kubectl, no cluster, no network):
#      canonical vs malformed stdout/stderr verdicts, the --kill-after=5s /
#      45s two-layer timeout on every lookup, 3 consecutive unknown lookups
#      failing closed (never zeroed), fail/fail/absent succeeding, and
#      present failing, then exit:
#
#        QR_APPLY_TEST_LOOKUP_SELF=1 .github/runner-scale-sets/query-regression/ack/apply-test.sh
#
# Steps:
#   1. kubectl client ABI check: the runner's kubectl must be exactly the
#      pinned v1.34.2 (the exec/cp protocol and the exec VAP allowlist are
#      pinned to it).
#   2. kubectl apply --dry-run=server for the VAPs and bindings (compiles
#      CEL). NOTE: server dry-run compiles the CEL and validates the binding
#      actions, but it does NOT exercise CONNECT/exec behavior; exec/cp
#      validation requires the real disposable canary (step 6).
#   3. Apply the real VAPs + enforcement bindings (["Deny","Audit"]; gated:
#      nothing in CI applies them automatically).
#   4. Inspect each VAP's status.typeChecking.expressionWarnings and the
#      TypeChecking condition: any warning/error fails the script.
#   5. Positive/negative Job + Pod probes via kubectl create --dry-run=server.
#      The positive manifest is generated by the trusted controller itself
#      (query-regression-ack-controller.py --dry-run) so the probe cannot
#      drift from the real rendered Job; negatives mutate that manifest
#      (appended bootstrap, duplicate/altered/missing/extra env, wrong image/
#      resources/TTL, hostNetwork, secret volume, valueFrom, wrong name) plus
#      a direct Pod (ownerReferences denial). Every negative mutation runs
#      through a stdin->stdout JSON pipeline (manifest JSON in, mutated JSON
#      out) that is proven offline first -- valid JSON out, expected field
#      changed -- before any mutated manifest is sent to the API server.
#   6. EXEC/CP CANARY -- the only step that creates real (disposable)
#      resources, and only when QR_APPLY_TEST_CANARY=1 is set. It creates one
#      conforming Job in query-regression-perf (the exact controller-rendered
#      manifest), waits for its pod, and runs positive exact-argv exec/cp
#      probes and negative arbitrary-shell/container/TTY/wrong-argv/wrong-path
#      probes against it, then deletes the canary Job (destructive to the
#      canary only; the namespace's ResourceQuota also prevents any second
#      Job while a real benchmark is running). Without the flag the script
#      exits 2: exec/cp CONNECT validation is a hard gate and must not be
#      claimed from dry-run alone.
#
# This script NEVER touches production resources other than its own disposable
# canary Job, and it never configures credentials. It targets only the
# query-regression-perf namespace (hard-coded, no override).
set -euo pipefail

NAMESPACE="query-regression-perf"
KUBECTL_PINNED_VERSION="v1.34.2"
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONTROLLER="$(realpath "${DIR}/../../../scripts/query-regression-ack-controller.py")"
PASS=0
FAIL=0
DENY_RE="denied the request|ValidatingAdmissionPolicy|is forbidden"

note() { printf '== %s\n' "$*"; }
ok() { PASS=$((PASS + 1)); printf 'ok: %s\n' "$*"; }
bad() { FAIL=$((FAIL + 1)); printf 'FAIL: %s\n' "$*" >&2; }

# Two-layer timeout for every canary Job lookup: kubectl's fixed
# --request-timeout plus a local coreutils `timeout` backstop (with a
# --kill-after=5s grace so a hung kubectl or exec credential plugin cannot
# linger) around the whole invocation. Every timeout is a failure: the get
# exits non-zero (timeout(1) exits 124, or 137 after the kill grace) and
# job_lookup_status maps every non-zero exit to status 2 (unknown), which the
# callers treat as a final failure -- absence is never inferred from a
# timeout.
JOB_LOOKUP_REQUEST_TIMEOUT="30s"
JOB_LOOKUP_LOCAL_TIMEOUT=45

# Fail-closed Job lookup (used for the canary). Distinguishes a successful
# empty get (absent), a successful present get, and failures: exit 0 = absent
# (proven), 1 = present, 2 = cannot determine (authorization/API/transport
# error, timeout from either of the two layers above, stderr pollution, or
# malformed stdout). stdout and stderr are captured SEPARATELY:
#   * rc != 0 -> 2 (unknown), whatever the streams contain;
#   * rc == 0 but stderr non-empty -> 2 (unknown): a successful get writes
#     nothing to stderr, so any stderr at all -- judged on the RAW bytes of
#     the capture file ([ -s ]), whitespace-only/newline-only noise included
#     -- makes the result non-canonical;
#   * rc == 0, stderr empty, raw empty stdout (zero bytes, no whitespace)
#     -> 0 (absent): the ONLY proof of absence;
#   * rc == 0, stderr empty, stdout exactly `job.batch/NAME` (optionally
#     with the single standard trailing newline) -> 1 (present);
#   * anything else (whitespace-only, leading/trailing spaces, wrong name,
#     multi-line, extra bytes) -> 2 (unknown): a malformed get must never be
#     read as either absent or present, or a still-running Job could be
#     reported deleted (fail-open).
job_lookup_status() {
  local ns="$1" job="$2"
  local out_file err_file rc
  local out_bytes out_text expected
  out_file="$(mktemp)"
  err_file="$(mktemp)"
  set +e
  timeout --kill-after=5s "${JOB_LOOKUP_LOCAL_TIMEOUT}" kubectl -n "${ns}" get job "${job}" --ignore-not-found -o name --request-timeout="${JOB_LOOKUP_REQUEST_TIMEOUT}" >"${out_file}" 2>"${err_file}"
  rc=$?
  set -e
  if [ "${rc}" -ne 0 ]; then
    echo "cannot determine Job ${job} in ${ns}: kubectl get failed (rc=${rc}): $(cat "${err_file}")" >&2
    rm -f "${out_file}" "${err_file}"
    return 2
  fi
  if [ -s "${err_file}" ]; then
    # Stderr pollution is judged on the RAW bytes of the capture file
    # ([ -s ]), never on a command substitution: `$(cat file)` strips
    # trailing newlines, so a newline-only stderr (exec-plugin noise that is
    # just a bare newline) would collapse to the empty string and be misread
    # as clean. Any non-zero byte count -- whitespace-only included -- makes
    # the result non-canonical (unknown/2).
    echo "cannot determine Job ${job} in ${ns}: kubectl get succeeded but wrote to stderr: $(cat "${err_file}")" >&2
    rm -f "${out_file}" "${err_file}"
    return 2
  fi
  out_bytes="$(wc -c < "${out_file}")"
  out_text="$(cat "${out_file}")"
  rm -f "${out_file}" "${err_file}"
  if [ "${out_bytes}" -eq 0 ]; then
    # Raw empty stdout (zero bytes, not even a newline): the ONLY proof of
    # absence. Whitespace-only output has a non-zero byte count and falls
    # through to the malformed branch below.
    return 0
  fi
  expected="job.batch/${job}"
  # The byte count distinguishes the canonical single trailing newline from
  # multi-line output: command substitution alone would collapse both into
  # the same string, so a "NAME\n\n" (multi-line) result is rejected here.
  if [ "${out_text}" = "${expected}" ]; then
    if [ "${out_bytes}" -eq "${#expected}" ] || [ "${out_bytes}" -eq $(( ${#expected} + 1 )) ]; then
      return 1
    fi
  fi
  echo "cannot determine Job ${job} in ${ns}: malformed kubectl get output (expected raw empty stdout or exactly '${expected}' with at most one trailing newline): $(printf '%s' "${out_text}" | head -c 200)" >&2
  return 2
}

# Bounded canary-absence confirmation (the final success conclusion of the
# canary cleanup). After the delete, the Job's absence is proven ONLY by a
# successful exact lookup (job_lookup_status -> 0); a failing lookup (status
# 2) is retried a bounded number of times so a transient failure does not
# immediately fail the run, but the verdict of the FINAL attempt is never
# reset -- three consecutive unknowns fail closed instead of being zeroed
# into a false "absent". Present (status 1) is a final failure too: the
# deletion is not confirmed. Returns 0 (confirmed absent), 1 (still present)
# or 2 (cannot determine after the bounded retries).
confirm_canary_absence() {
  local ns="$1" job="$2"
  local canary_status=0
  local confirm_attempt=1
  while [ "${confirm_attempt}" -le 3 ]; do
    canary_status=0
    job_lookup_status "${ns}" "${job}" || canary_status=$?
    if [ "${canary_status}" -eq 0 ] || [ "${canary_status}" -eq 1 ]; then
      break
    fi
    # canary_status=2 (cannot determine): transient or persistent lookup
    # failure; retry within the bounded loop. The reset happens before each
    # lookup, never after, so the final attempt's unknown verdict survives
    # the loop and fails the cleanup instead of being zeroed into "absent".
    if [ "${confirm_attempt}" -lt 3 ]; then
      sleep 2
    fi
    confirm_attempt=$((confirm_attempt + 1))
  done
  return "${canary_status}"
}

command -v python3 >/dev/null 2>&1 || { echo "python3 is required (controller manifest generation)" >&2; exit 1; }
[ -f "${CONTROLLER}" ] || { echo "controller not found: ${CONTROLLER}" >&2; exit 1; }

# QR_APPLY_TEST_SELF=1 runs only the offline negative-mutation self-test
# (every mutation must emit valid JSON and change the expected field) with no
# kubectl and no cluster, then exits. QR_APPLY_TEST_LOOKUP_SELF=1 runs only
# the offline PATH-stub behavior suite for the fail-closed Job lookup and the
# canary cleanup confirmation state machine (stub kubectl/timeout binaries on
# a temporary PATH; no cluster, no network), then exits. kubectl is only
# required for the server-side steps.
SELF_TEST_ONLY=0
if [ "${QR_APPLY_TEST_SELF:-0}" = "1" ]; then
  SELF_TEST_ONLY=1
fi
LOOKUP_SELF_TEST_ONLY=0
if [ "${QR_APPLY_TEST_LOOKUP_SELF:-0}" = "1" ]; then
  LOOKUP_SELF_TEST_ONLY=1
fi
if [ "${SELF_TEST_ONLY}" != "1" ] && [ "${LOOKUP_SELF_TEST_ONLY}" != "1" ]; then
  command -v kubectl >/dev/null 2>&1 || { echo "kubectl is required" >&2; exit 1; }
fi

# The policies are namespace-scoped to query-regression-perf; refuse anything
# that would point them (or the canary) elsewhere.
if [ "${QUERY_REGRESSION_NAMESPACE:-${NAMESPACE}}" != "${NAMESPACE}" ]; then
  echo "FAIL: this script targets only namespace ${NAMESPACE}; QUERY_REGRESSION_NAMESPACE is not honored" >&2
  exit 1
fi

# The positive Job manifest is rendered by the trusted controller itself, so
# it is byte-for-byte the shape a real run would create (env contract,
# bootstrap args, resources, security, volumes, labels, annotations, TTL,
# podReplacementPolicy, node placement). SOURCE_RUN_ID must be a valid run id
# for the deterministic Job name.
gen_conforming_manifest() {
  local run_id="$1"
  SOURCE_RUN_ID="${run_id}" \
  SOURCE_RUN_ATTEMPT="1" \
  VERIFIED_BASE_SHA="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" \
  VERIFIED_CANDIDATE_SHA="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb" \
  CASE_PATHS="all" \
  HTTP_TIMEOUT="300" \
  ALLOW_LARGE_FIXTURE="true" \
  RUN_URL="https://github.com/GreptimeTeam/greptimedb/actions/runs/${run_id}" \
  CASE_NAME="apply-test-canary" \
  CARGO_PROFILE="nightly" \
  python3 "${CONTROLLER}" --dry-run
}

# Negative Job mutations. Each entry is "name|python snippet|python check".
# The snippet runs with the conforming manifest JSON on stdin bound to `m`
# and must emit the mutated manifest JSON on stdout; the check runs against
# the original (`a`) and mutated (`b`) manifests and must be truthy exactly
# when the mutation changed the expected field. The same table drives both
# the offline self-test and the server-side probes (step 5), so a mutation
# can never be probed against the API server without being proven first.
MUTATIONS=(
  'appended bootstrap|m["spec"]["template"]["spec"]["containers"][0]["args"][0] += "\n# escape"|b["spec"]["template"]["spec"]["containers"][0]["args"][0] != a["spec"]["template"]["spec"]["containers"][0]["args"][0]'
  'duplicate env entry|m["spec"]["template"]["spec"]["containers"][0]["env"].append({"name": "BASE_BIN", "value": "/payload/bins/base/greptime"})|len(b["spec"]["template"]["spec"]["containers"][0]["env"]) == len(a["spec"]["template"]["spec"]["containers"][0]["env"]) + 1'
  'altered env value|next(e for e in m["spec"]["template"]["spec"]["containers"][0]["env"] if e["name"] == "BASE_BIN")["value"] = "/tmp/evil"|next(e["value"] for e in b["spec"]["template"]["spec"]["containers"][0]["env"] if e["name"] == "BASE_BIN") == "/tmp/evil"'
  'missing env entry|m["spec"]["template"]["spec"]["containers"][0]["env"] = [e for e in m["spec"]["template"]["spec"]["containers"][0]["env"] if e["name"] != "GITHUB_OUTPUT"]|len(b["spec"]["template"]["spec"]["containers"][0]["env"]) == len(a["spec"]["template"]["spec"]["containers"][0]["env"]) - 1 and all(e["name"] != "GITHUB_OUTPUT" for e in b["spec"]["template"]["spec"]["containers"][0]["env"])'
  'extra env name|m["spec"]["template"]["spec"]["containers"][0]["env"].append({"name": "FOO", "value": "bar"})|any(e["name"] == "FOO" for e in b["spec"]["template"]["spec"]["containers"][0]["env"])'
  'env secret reference|m["spec"]["template"]["spec"]["containers"][0]["env"].append({"name": "SECRET", "valueFrom": {"secretKeyRef": {"name": "x", "key": "y"}}})|any("valueFrom" in e and "secretKeyRef" in e["valueFrom"] for e in b["spec"]["template"]["spec"]["containers"][0]["env"])'
  'wrong image|m["spec"]["template"]["spec"]["containers"][0]["image"] = "example.com/runner:latest"|b["spec"]["template"]["spec"]["containers"][0]["image"] == "example.com/runner:latest"'
  'wrong resources|m["spec"]["template"]["spec"]["containers"][0]["resources"]["limits"]["cpu"] = "16"|b["spec"]["template"]["spec"]["containers"][0]["resources"]["limits"]["cpu"] == "16"'
  'wrong TTL|m["spec"]["ttlSecondsAfterFinished"] = 0|b["spec"]["ttlSecondsAfterFinished"] == 0'
  'suspend true|m["spec"]["suspend"] = True|b["spec"]["suspend"] is True'
  'nodeName pin|m["spec"]["template"]["spec"]["nodeName"] = "some-other-node"|b["spec"]["template"]["spec"]["nodeName"] == "some-other-node"'
  'custom schedulerName|m["spec"]["template"]["spec"]["schedulerName"] = "evil-scheduler"|b["spec"]["template"]["spec"]["schedulerName"] == "evil-scheduler"'
  'priorityClassName|m["spec"]["template"]["spec"]["priorityClassName"] = "high-priority"|b["spec"]["template"]["spec"]["priorityClassName"] == "high-priority"'
  'priority|m["spec"]["template"]["spec"]["priority"] = 100|b["spec"]["template"]["spec"]["priority"] == 100'
  'affinity|m["spec"]["template"]["spec"]["affinity"] = {"nodeAffinity": {"requiredDuringSchedulingIgnoredDuringExecution": {"nodeSelectorTerms": [{"matchExpressions": [{"key": "kubernetes.io/hostname", "operator": "In", "values": ["other"]}]}]}}}|b["spec"]["template"]["spec"]["affinity"]["nodeAffinity"]["requiredDuringSchedulingIgnoredDuringExecution"]["nodeSelectorTerms"][0]["matchExpressions"][0]["values"] == ["other"]'
  'schedulingGates|m["spec"]["template"]["spec"]["schedulingGates"] = [{"name": "example.com/gate"}]|b["spec"]["template"]["spec"]["schedulingGates"] == [{"name": "example.com/gate"}]'
  'hostNetwork|m["spec"]["template"]["spec"]["hostNetwork"] = True|b["spec"]["template"]["spec"]["hostNetwork"] is True'
  'secret volume|m["spec"]["template"]["spec"]["volumes"].append({"name": "sec", "secret": {"secretName": "x"}})|any("secret" in v for v in b["spec"]["template"]["spec"]["volumes"])'
  'non-deterministic name|m["metadata"]["name"] = "evil-job"|b["metadata"]["name"] == "evil-job"'
)

# Wraps a mutation snippet into a stdin->stdout JSON pipeline: reads the
# manifest JSON from stdin into `m`, applies the snippet, emits the mutated
# manifest JSON on stdout. Shared by run_mutation_self_test and
# probe_negative_job so the proven pipeline is exactly the probed one.
run_mutation() {
  local py="$1"
  python3 -c "import json, sys
m = json.load(sys.stdin)
${py}
json.dump(m, sys.stdout)"
}

# Evaluates a mutation check expression against two manifests: `a` is the
# original conforming manifest, `b` is the candidate. Exits 0 iff the check
# is truthy. Used to prove both directions: the check must hold for the
# mutated manifest and must NOT hold for the original (a vacuous check that
# the conforming manifest already satisfies proves nothing).
check_mutation() {
  local orig="$1" candidate="$2" expr="$3"
  python3 -c "import json, sys
a = json.loads(sys.argv[1])
b = json.loads(sys.argv[2])
sys.exit(0 if (${expr}) else 1)" "${orig}" "${candidate}"
}

# Offline, no-cluster proof that every negative mutation emits valid JSON and
# changes the expected field. No kubectl, no API server. Run it before any
# mutated manifest is sent to kubectl create --dry-run=server.
run_mutation_self_test() {
  local conforming="$1"
  local failed=0
  local entry name py check output
  for entry in "${MUTATIONS[@]}"; do
    IFS='|' read -r name py check <<<"${entry}"
    output="$(printf '%s' "${conforming}" | run_mutation "${py}" 2>&1 || true)"
    if ! printf '%s' "${output}" | python3 -c 'import json, sys; json.load(sys.stdin)' 2>/dev/null; then
      bad "mutation self-test: ${name} did not emit valid JSON on stdout: $(printf '%s' "${output}" | head -c 200)"
      failed=1
      continue
    fi
    if ! check_mutation "${conforming}" "${output}" "${check}"; then
      bad "mutation self-test: ${name} did not change the expected field"
      failed=1
      continue
    fi
    # ... and must NOT already hold for the original manifest. A KeyError
    # here just means the field is absent from the conforming manifest (the
    # expected proof); stderr is suppressed so legitimately-absent fields do
    # not look like failures. The mutated-direction check above keeps stderr
    # visible so a real mutation bug (e.g. a field the mutation was supposed
    # to add) is debuggable.
    if check_mutation "${conforming}" "${conforming}" "${check}" 2>/dev/null; then
      bad "mutation self-test: ${name} check is vacuous (already true for the conforming manifest)"
      failed=1
      continue
    fi
    ok "mutation self-test: ${name} changes the expected field"
  done
  return "${failed}"
}

# Offline PATH-stub behavior suite for job_lookup_status and
# confirm_canary_absence. Writes stub `kubectl` and `timeout` executables to a
# temporary directory, prepends it to PATH, and drives the REAL functions
# through every canonical/malformed stdout+stderr shape and the bounded
# cleanup-confirmation state machine. No real kubectl, no cluster, no
# network: every kubectl/timeout behavior below comes from the temporary
# PATH stubs. The stub timeout asserts the exact two-layer invocation shape
# (--kill-after=5s and the 45-second budget) on every lookup, so a change to
# the timeout wrapper fails the suite behaviorally.
run_lookup_behavior_self_test() {
  local work failed saved_path
  work="$(mktemp -d)"
  failed=0
  saved_path="${PATH}"

  cat > "${work}/timeout" <<'STUB'
#!/usr/bin/env bash
set -u
# Stub coreutils timeout: the local backstop must wrap every canary lookup
# with exactly --kill-after=5s and a 45-second budget, then forward to the
# (stub) kubectl on the same PATH. Any other invocation shape is a failure:
# the outer command then exits non-zero and job_lookup_status maps it to
# unknown/2, which the exact-output scenarios below catch.
if [ "${1:-}" != "--kill-after=5s" ]; then
  echo "stub timeout: expected --kill-after=5s as argv1, got '${1:-}'" >&2
  exit 125
fi
if [ "${2:-}" != "45" ]; then
  echo "stub timeout: expected a 45-second budget as argv2, got '${2:-}'" >&2
  exit 125
fi
count_file="${TIMEOUT_STUB_COUNT:-}"
if [ -n "${count_file}" ]; then
  n=0
  [ -f "${count_file}" ] && n="$(cat "${count_file}")"
  n=$((n + 1))
  echo "${n}" > "${count_file}"
fi
shift 2
exec kubectl "$@"
STUB

  cat > "${work}/kubectl" <<'STUB'
#!/usr/bin/env bash
set -u
scenario="${LOOKUP_STUB_SCENARIO:?missing LOOKUP_STUB_SCENARIO}"
count_file="${LOOKUP_STUB_COUNT:?missing LOOKUP_STUB_COUNT}"
n=0
[ -f "${count_file}" ] && n="$(cat "${count_file}")"
n=$((n + 1))
echo "${n}" > "${count_file}"
# job_lookup_status invokes: kubectl -n <ns> get job <job> --ignore-not-found
# -o name --request-timeout=30s; recover the Job name for the exact-present
# scenarios.
job=""
prev=""
for a in "$@"; do
  if [ "${prev}" = "job" ]; then
    job="${a}"
  fi
  prev="${a}"
done
case "${scenario}" in
  absent) exit 0 ;;
  fail)
    echo "Error from server (InternalError): simulated API failure" >&2
    exit 1
    ;;
  fail-twice-then-absent)
    if [ "${n}" -le 2 ]; then
      echo "Error from server (InternalError): simulated API failure" >&2
      exit 1
    fi
    exit 0
    ;;
  present) printf 'job.batch/%s' "${job}"; exit 0 ;;
  present-newline) printf 'job.batch/%s\n' "${job}"; exit 0 ;;
  whitespace-only) printf '   \n'; exit 0 ;;
  padded) printf '  job.batch/%s\n' "${job}"; exit 0 ;;
  wrong-name) printf 'job.batch/some-other-job\n'; exit 0 ;;
  multiline) printf 'job.batch/%s\njob.batch/some-other-job\n' "${job}"; exit 0 ;;
  double-newline) printf 'job.batch/%s\n\n' "${job}"; exit 0 ;;
  stderr-pollution)
    printf 'job.batch/%s' "${job}"
    echo 'time="2026-01-01T00:00:00Z" level=warning msg="exec plugin noise"' >&2
    exit 0
    ;;
  stderr-whitespace-only)
    printf 'job.batch/%s' "${job}"
    printf '   \n' >&2
    exit 0
    ;;
  stderr-newline-only)
    printf 'job.batch/%s' "${job}"
    printf '\n' >&2
    exit 0
    ;;
  *)
    echo "unknown lookup stub scenario: ${scenario}" >&2
    exit 125
    ;;
esac
STUB
  chmod +x "${work}/timeout" "${work}/kubectl"
  PATH="${work}:${saved_path}"
  export PATH

  check_lookup_verdict() {
    local scenario="$1" expected="$2" rc
    rc=0
    LOOKUP_STUB_SCENARIO="${scenario}" LOOKUP_STUB_COUNT="${work}/count-lookup-${scenario}" \
      job_lookup_status "${NAMESPACE}" "query-regression-9001-1" || rc=$?
    if [ "${rc}" -eq "${expected}" ]; then
      ok "lookup self-test: ${scenario} -> ${rc} (expected ${expected})"
    else
      bad "lookup self-test: ${scenario} -> ${rc}, expected ${expected}"
      failed=1
    fi
  }

  check_lookup_verdict absent 0
  check_lookup_verdict present 1
  check_lookup_verdict present-newline 1
  check_lookup_verdict whitespace-only 2
  check_lookup_verdict padded 2
  check_lookup_verdict wrong-name 2
  check_lookup_verdict multiline 2
  check_lookup_verdict double-newline 2
  check_lookup_verdict stderr-pollution 2
  check_lookup_verdict stderr-whitespace-only 2
  check_lookup_verdict stderr-newline-only 2
  check_lookup_verdict fail 2

  # The bounded canary cleanup confirmation state machine (real function,
  # real stub binaries): 3 consecutive unknowns must fail closed and never be
  # zeroed into a false "absent"; fail/fail/absent may succeed; present must
  # fail.
  check_confirmation() {
    local scenario="$1" expected="$2" rc
    rc=0
    LOOKUP_STUB_SCENARIO="${scenario}" LOOKUP_STUB_COUNT="${work}/count-conf-${scenario}" \
      TIMEOUT_STUB_COUNT="${work}/timeout-count-conf-${scenario}" \
      confirm_canary_absence "${NAMESPACE}" "query-regression-9001-1" || rc=$?
    if [ "${rc}" -eq "${expected}" ]; then
      ok "cleanup confirmation self-test: ${scenario} -> ${rc} (expected ${expected})"
    else
      bad "cleanup confirmation self-test: ${scenario} -> ${rc}, expected ${expected}"
      failed=1
    fi
  }

  check_confirmation fail 2
  check_confirmation fail-twice-then-absent 0
  check_confirmation present 1

  # Every lookup must have gone through the two-layer timeout stub: the
  # all-fail confirmation scenario issued exactly 3 lookups (and 3 local
  # timeout backstops) before failing closed.
  local fail_count fail_timeouts
  fail_count=0
  [ -f "${work}/count-conf-fail" ] && fail_count="$(cat "${work}/count-conf-fail")"
  fail_timeouts=0
  [ -f "${work}/timeout-count-conf-fail" ] && fail_timeouts="$(cat "${work}/timeout-count-conf-fail")"
  if [ "${fail_count}" -eq 3 ] && [ "${fail_timeouts}" -eq 3 ]; then
    ok "cleanup confirmation self-test: all-fail scenario issued 3 lookups, each wrapped by the local timeout backstop"
  else
    bad "cleanup confirmation self-test: all-fail scenario issued ${fail_count} lookups and ${fail_timeouts} timeout backstops (expected 3 and 3)"
    failed=1
  fi

  PATH="${saved_path}"
  export PATH
  rm -rf "${work}"
  return "${failed}"
}

if [ "${SELF_TEST_ONLY}" = "1" ]; then
  note "offline negative-mutation self-test (no kubectl, no cluster)"
  CONFORMING="$(gen_conforming_manifest 9001)"
  run_mutation_self_test "${CONFORMING}" || FAIL=$((FAIL + 1))
  printf '\npolicy apply-test: %d ok, %d failed\n' "${PASS}" "${FAIL}"
  if [ "${FAIL}" -gt 0 ]; then
    exit 1
  fi
  exit 0
fi

if [ "${LOOKUP_SELF_TEST_ONLY}" = "1" ]; then
  note "offline PATH-stub job lookup + cleanup confirmation behavior (no kubectl, no cluster)"
  run_lookup_behavior_self_test || FAIL=$((FAIL + 1))
  printf '\npolicy apply-test: %d ok, %d failed\n' "${PASS}" "${FAIL}"
  if [ "${FAIL}" -gt 0 ]; then
    exit 1
  fi
  exit 0
fi

note "Step 1: kubectl client ABI pin"
KUBECTL_VERSION="$(kubectl version --client -o json 2>/dev/null | python3 -c 'import json,sys; print(json.load(sys.stdin)["clientVersion"].get("gitVersion",""))' 2>/dev/null || true)"
if [ "${KUBECTL_VERSION}" = "${KUBECTL_PINNED_VERSION}" ]; then
  ok "kubectl client is the pinned ABI ${KUBECTL_PINNED_VERSION}"
else
  echo "FAIL: kubectl client version '${KUBECTL_VERSION}' does not match the pinned ABI ${KUBECTL_PINNED_VERSION}" >&2
  echo "      the exec/cp protocol and the exec VAP allowlist are pinned to this exact version" >&2
  exit 1
fi

note "Step 2: server-side dry-run apply of VAPs and bindings (compiles CEL; NOT a CONNECT/exec validation)"
if kubectl apply --dry-run=server -f "${DIR}/validatingadmissionpolicy.yaml" \
    -f "${DIR}/validatingadmissionpolicybinding.yaml" >/dev/null; then
  ok "VAPs and bindings accepted by the API server (CEL compiled, actions valid)"
else
  bad "VAPs/bindings rejected by the API server; fix the CEL before deploying"
  exit 1
fi

note "Step 3: apply the deployment-gated VAPs and enforcement bindings (Deny+Audit)"
kubectl apply -f "${DIR}/validatingadmissionpolicy.yaml" \
  -f "${DIR}/validatingadmissionpolicybinding.yaml" >/dev/null
ok "deployment-gated VAPs and bindings applied"

note "Step 4: inspect typeChecking status (expressionWarnings must be empty)"
check_typechecking() {
  local name="$1"
  local warnings="" condition=""
  local deadline=$(( $(date +%s) + 90 ))
  until [ -n "${condition}" ] || [ "$(date +%s)" -ge "${deadline}" ]; do
    condition="$(kubectl get validatingadmissionpolicy "${name}" -o jsonpath='{.status.conditions[?(@.type=="TypeChecking")].status}' 2>/dev/null || true)"
    [ -n "${condition}" ] || sleep 3
  done
  warnings="$(kubectl get validatingadmissionpolicy "${name}" -o jsonpath='{.status.typeChecking.expressionWarnings}' 2>/dev/null || true)"
  if [ "${condition}" != "True" ]; then
    bad "typeChecking condition for ${name} is not True (got '${condition}'); CEL does not type-check on this server"
    return 1
  fi
  if [ -n "${warnings}" ] && [ "${warnings}" != "[]" ]; then
    bad "typeChecking expressionWarnings for ${name}: ${warnings}"
    return 1
  fi
  ok "typeChecking clean for ${name}"
}
check_typechecking "query-regression-workload"
check_typechecking "query-regression-pods"
check_typechecking "query-regression-exec"

note "Step 5: positive/negative probes (server dry-run; nothing is created)"
CONFORMING="$(gen_conforming_manifest 9001)"
# Prove every mutation offline (valid JSON out, expected field changed) before
# any mutated manifest reaches the API server; the probes below feed kubectl
# through the very same run_mutation pipeline.
if ! run_mutation_self_test "${CONFORMING}"; then
  bad "offline mutation self-test failed; refusing to send unproven mutations to the API server"
  exit 1
fi
if printf '%s' "${CONFORMING}" | kubectl create --dry-run=server -f - -o name >/dev/null 2>&1; then
  ok "conforming controller-rendered Job allowed"
else
  bad "conforming controller-rendered Job was denied; the policy is too strict"
fi

# Negative probes mutate the conforming manifest through the same
# stdin->stdout JSON pipeline as the self-test (manifest JSON in, mutated
# manifest JSON out) and feed the result to kubectl create --dry-run=server.
# The probe passes only when the API server rejects the mutation with a
# ValidatingAdmissionPolicy denial message.
probe_negative_job() {
  local name="$1" py="$2"
  local output
  output="$(printf '%s' "${CONFORMING}" | run_mutation "${py}" | kubectl create --dry-run=server -f - -o name 2>&1 || true)"
  if [ -z "${output}" ]; then
    bad "${name}: expected denial but the request was allowed"
  elif grep -qE "denied the request|ValidatingAdmissionPolicy" <<<"${output}"; then
    ok "${name} denied"
  else
    bad "${name}: rejected but without a VAP denial message: $(printf '%s' "${output}" | head -c 300)"
  fi
}

for entry in "${MUTATIONS[@]}"; do
  IFS='|' read -r name py _ <<<"${entry}"
  probe_negative_job "${name}" "${py}"
done

# Direct pod creation (ownerReferences are set by the Job controller, not by
# clients): a well-formed-looking pod WITHOUT an ownerReference must be denied.
DIRECT_POD="
apiVersion: v1
kind: Pod
metadata:
  name: query-regression-9001-1-abcde
  namespace: ${NAMESPACE}
  labels: {app: query-regression, run-id: '9001', run-attempt: '1'}
spec:
  restartPolicy: Never
  containers:
    - name: benchmark
      image: greptime-registry.cn-hangzhou.cr.aliyuncs.com/greptime/greptimedb-query-regression-runner@sha256:e713b294e23b7e15184e558866c90025e59930033e72c97650dbc7f1ca022d11
"
if printf '%s' "${DIRECT_POD}" | kubectl create --dry-run=server -f - -o name >/dev/null 2>&1; then
  bad "direct pod creation: expected denial but the request was allowed"
else
  ok "direct pod creation denied (ownerReferences check)"
fi

if [ "${QR_APPLY_TEST_CANARY:-0}" != "1" ]; then
  printf '\nEXEC/CP CONNECT VALIDATION IS A HARD GATE: server dry-run does not exercise CONNECT.\n' >&2
  printf 'Re-run with QR_APPLY_TEST_CANARY=1 to create a disposable canary Job in %s,\n' "${NAMESPACE}" >&2
  printf 'probe exact exec/cp argv+stream tuples, and delete it (destructive to the canary only).\n' >&2
  exit 2
fi

note "Step 6: real disposable canary in ${NAMESPACE} (explicit operator invocation; destructive to the canary Job only)"
CANARY_RUN_ID="${QR_CANARY_RUN_ID:-42424242}"
CANARY_JOB="query-regression-${CANARY_RUN_ID}-1"
CANARY_NS="${NAMESPACE}"
canary_status=0
job_lookup_status "${CANARY_NS}" "${CANARY_JOB}" || canary_status=$?
if [ "${canary_status}" -eq 2 ]; then
  bad "cannot confirm whether canary Job ${CANARY_JOB} exists in ${CANARY_NS}; refusing to proceed (fail closed)"
  FAIL=1
elif [ "${canary_status}" -eq 1 ]; then
  bad "canary Job ${CANARY_JOB} already exists in ${CANARY_NS}; refusing to touch it (set QR_CANARY_RUN_ID to another id)"
  FAIL=1
else
  CANARY_POD=""
  cleanup_canary() {
    kubectl -n "${CANARY_NS}" delete job "${CANARY_JOB}" --cascade=foreground --wait=true --timeout=180s >/dev/null 2>&1 || true
    # Absence is proven only by a successful empty get (rc=0, no output); a
    # failing get (403/transport/timeout) means the deletion is NOT confirmed.
    # The confirmation lookup is retried a bounded number of times so a
    # transient lookup failure does not immediately fail the run -- but only a
    # successful empty get ever proves absence; a persistent "cannot
    # determine" verdict after the retries is a final failure (fail closed).
    canary_status=0
    confirm_canary_absence "${CANARY_NS}" "${CANARY_JOB}" || canary_status=$?
    if [ "${canary_status}" -eq 2 ]; then
      bad "cannot confirm canary Job ${CANARY_JOB} deletion in ${CANARY_NS} (kubectl get failed after 3 attempts); deletion NOT confirmed"
    elif [ "${canary_status}" -eq 1 ]; then
      bad "canary Job ${CANARY_JOB} still present after delete"
    else
      ok "canary Job ${CANARY_JOB} deleted"
    fi
  }
  trap 'cleanup_canary >/dev/null 2>&1 || true' EXIT

  if printf '%s' "$(gen_conforming_manifest "${CANARY_RUN_ID}")" | kubectl create -f - -o name >/dev/null 2>&1; then
    ok "canary Job ${CANARY_JOB} created (real create; also a positive workload-VAP test)"
  else
    bad "canary Job creation failed (quota may be occupied by a real benchmark, or the workload VAP denied it)"
    exit 1
  fi

  # Wait for the pod (image pull + node scheduling), bounded.
  deadline=$(( $(date +%s) + 900 ))
  until [ "$(date +%s)" -ge "${deadline}" ]; do
    CANARY_POD="$(kubectl -n "${CANARY_NS}" get pods -l job-name="${CANARY_JOB}" -o jsonpath='{.items[0].metadata.name}' 2>/dev/null || true)"
    [ -n "${CANARY_POD}" ] && break
    sleep 5
  done
  if [ -z "${CANARY_POD}" ]; then
    bad "canary pod did not appear within 15 minutes"
    exit 1
  fi
  phase=""
  until [ "$(date +%s)" -ge "${deadline}" ]; do
    phase="$(kubectl -n "${CANARY_NS}" get pod "${CANARY_POD}" -o jsonpath='{.status.phase}' 2>/dev/null || true)"
    case "${phase}" in
      Running) break ;;
      Succeeded|Failed) bad "canary pod reached ${phase}; cannot run exec/cp probes"; exit 1 ;;
      *) sleep 5 ;;
    esac
  done
  if [ "${phase}" != "Running" ]; then
    bad "canary pod ${CANARY_POD} not Running within 15 minutes (last phase '${phase}')"
    exit 1
  fi
  ok "canary pod ${CANARY_POD} is Running"

  # exec_probe: admitted iff no ValidatingAdmissionPolicy denial text appears
  # (the command itself may exit non-zero for canary-state reasons -- e.g.
  # /work/.done absent -- which is fine; only admission is being tested).
  exec_probe() {
    local out err
    out="$(mktemp)"; err="$(mktemp)"
    set +e
    kubectl -n "${CANARY_NS}" exec "${CANARY_POD}" "$@" >"${out}" 2>"${err}"
    set -e
    if grep -qE "${DENY_RE}" "${out}" "${err}"; then
      rm -f "${out}" "${err}"
      return 1
    fi
    rm -f "${out}" "${err}"
    return 0
  }

  note "positive exec: exact canonical argv tuples must be admitted"
  exec_probe -- sh -c 'cat /work/benchmark-status 2>/dev/null || true' && ok "exec admitted: cat benchmark-status" || bad "exec denied: cat benchmark-status"
  exec_probe -- sh -c 'test -f /work/.done' && ok "exec admitted: test -f /work/.done" || bad "exec denied: test -f /work/.done"
  exec_probe -- sh -c 'touch /work/.collected' && ok "exec admitted: touch /work/.collected" || bad "exec denied: touch /work/.collected"
  exec_probe -- sh -c 'test -f /payload/run.sh && test -d /payload/bins/base && test -d /payload/bins/candidate && test -d /payload/repo/tests/perf/query_cases' && ok "exec admitted: payload layout check" || bad "exec denied: payload layout check"
  exec_probe -- sh -c 'chmod +x /payload/run.sh /payload/bins/base/greptime /payload/bins/candidate/greptime /payload/bins/candidate/query_perf_fixture /payload/bins/candidate/query_regression_runner' && ok "exec admitted: payload chmod" || bad "exec denied: payload chmod"
  exec_probe -- sh -c 'sha256sum /payload/bins/base/greptime /payload/bins/candidate/greptime /payload/bins/candidate/query_perf_fixture /payload/bins/candidate/query_regression_runner' && ok "exec admitted: sha256sum" || bad "exec denied: sha256sum"
  # touch /payload/.ready wakes the canary bootstrap, which then exits because
  # /payload/run.sh is absent -> run it last.
  exec_probe -- sh -c 'touch /payload/.ready' && ok "exec admitted: touch /payload/.ready" || bad "exec denied: touch /payload/.ready"

  note "positive cp: canonical kubectl cp tuples must be admitted"
  # cp_probe: admitted iff no ValidatingAdmissionPolicy denial text appears;
  # tar may still fail for canary-state reasons (e.g. an absent remote file).
  cp_probe() {
    local out err
    out="$(mktemp)"; err="$(mktemp)"
    set +e
    kubectl -n "${CANARY_NS}" cp "$@" >"${out}" 2>"${err}"
    set -e
    if grep -qE "${DENY_RE}" "${out}" "${err}"; then
      rm -f "${out}" "${err}"
      return 1
    fi
    rm -f "${out}" "${err}"
    return 0
  }
  probe_file="$(mktemp)"
  printf 'query-regression-ack canary probe\n' > "${probe_file}"
  cp_probe "${probe_file}" "${CANARY_POD}:/payload/" && ok "cp push to /payload admitted" || bad "cp push to /payload denied by the VAP"
  cp_probe "${CANARY_POD}:/work/query-regression-work" "$(mktemp -d)/" && ok "cp pull of /work/query-regression-work admitted" || bad "cp pull of /work/query-regression-work denied by the VAP"
  cp_probe "${CANARY_POD}:/work/query-regression-summary.md" "$(mktemp)/summary.md" && ok "cp pull of /work/query-regression-summary.md admitted" || bad "cp pull of /work/query-regression-summary.md denied by the VAP"

  note "negative exec: arbitrary shell/argv/container/TTY/stdin tuples must be denied"
  exec_probe -- sh -c 'id' && bad "exec allowed: sh -c 'id'" || ok "exec denied: arbitrary shell 'id'"
  exec_probe -- ls / && bad "exec allowed: ls /" || ok "exec denied: arbitrary argv ls /"
  exec_probe -- sh -c 'touch /work/evil' && bad "exec allowed: touch /work/evil" || ok "exec denied: unlisted script touch /work/evil"
  exec_probe -c other -- sh -c 'cat /work/benchmark-status 2>/dev/null || true' && bad "exec allowed: wrong container" || ok "exec denied: wrong container"
  if exec_probe -i -- sh -c 'cat /work/benchmark-status 2>/dev/null || true' </dev/null; then
    bad "exec allowed: stdin=true tuple"
  else
    ok "exec denied: stdin=true tuple (kubectl exec -i)"
  fi
  if command -v script >/dev/null 2>&1; then
    tty_out="$(script -qec "kubectl -n ${CANARY_NS} exec -it ${CANARY_POD} -- sh -c 'cat /work/benchmark-status 2>/dev/null || true'" /dev/null 2>&1 || true)"
    if grep -qE "${DENY_RE}" <<<"${tty_out}"; then
      ok "exec denied: interactive TTY (tty=true)"
    else
      bad "exec with TTY: no VAP denial observed: $(printf '%s' "${tty_out}" | head -c 300)"
    fi
  else
    note "script(1) unavailable; TTY probe skipped (the VAP still enforces tty=false)"
  fi

  note "negative cp: wrong destination/source paths must be denied"
  cp_probe "${probe_file}" "${CANARY_POD}:/etc/" && bad "cp push to /etc allowed" || ok "cp push to /etc denied"
  cp_probe "${CANARY_POD}:/etc/passwd" "$(mktemp)/pw" && bad "cp pull of /etc/passwd allowed" || ok "cp pull of /etc/passwd denied"
  cp_probe "${CANARY_POD}:/work/query-regression-work/evil" "$(mktemp)/evil" && bad "cp pull of unlisted work path allowed" || ok "cp pull of unlisted work path denied"
  rm -f "${probe_file}"

  cleanup_canary
  trap - EXIT
fi

printf '\npolicy apply-test: %d ok, %d failed\n' "${PASS}" "${FAIL}"
if [ "${FAIL}" -gt 0 ]; then
  exit 1
fi
